<template><StatusBanner :tone="available ? 'success' : 'warning'" :title="t('race.preview')"><span>{{ available ? `${preview?.count || placement?.ready || 0} ready` : (placement?.reason || t('race.noLineup')) }}</span><span v-if="preview?.mode"><code>mode</code>: {{ preview.mode }}</span></StatusBanner></template>
<script setup>import { computed } from "vue"; import { useStores } from "../../stores"; import StatusBanner from "../common/StatusBanner.vue"; const stores = useStores(); const { t } = stores.i18n; const placement = computed(() => stores.race.state.spawnDirector?.placement || {}); const preview = computed(() => stores.race.state.spawnDirector?.preview); const available = computed(() => placement.value.available === true || Number(preview.value?.count || 0) > 0)</script>
